cat <<'EOF' > src/shared.rs
use serde::{Deserialize, Serialize};
use uuid::Uuid;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt};

#[derive(Serialize, Deserialize, Debug)]
pub enum ControlMessage {
    Challenge(Uuid),
    Authenticate(String),
    Hello(u16),
    Connection(Uuid),
    Accept(Uuid),
    Heartbeat,
    Error(String),
}

pub async fn send_message<W>(writer: &mut W, msg: &ControlMessage) -> anyhow::Result<()>
where
    W: AsyncWriteExt + Unpin,
{
    let mut data = serde_json::to_vec(msg)?;
    data.push(0);
    writer.write_all(&data).await?;
    Ok(())
}

pub async fn recv_message<R>(reader: &mut R) -> anyhow::Result<ControlMessage>
where
    R: AsyncBufReadExt + Unpin,
{
    let mut buf = Vec::new();
    reader.read_until(0, &mut buf).await?;
    if buf.is_empty() {
        return Err(anyhow::anyhow!("Connection closed"));
    }
    buf.pop(); // remove null terminator
    let msg = serde_json::from_slice(&buf)?;
    Ok(msg)
}
EOF
"}

