use crate::shared::{recv_message, send_message, ControlMessage};
use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::Arc;
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::Mutex;
use uuid::Uuid;
use tracing::{info, warn, error, instrument};

pub async fn run(
    min_port: u16,
    max_port: u16,
    secret: Option<String>,
    bind_addr: String,
    bind_tunnels: Option<String>,
) -> anyhow::Result<()> {
    let bind_addr: SocketAddr = format!("{}:7835", bind_addr).parse()?;
    let listener = TcpListener::bind(bind_addr).await?;
    info!(addr = %bind_addr.ip(), "server listening");

    let state = Arc::new(Mutex::new(ServerState {
        tunnels: HashMap::new(),
    }));

    loop {
        let (stream, addr) = listener.accept().await?;
        let state = Arc::clone(&state);
        let secret = secret.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_connection(stream, addr, state, secret).await {
                // error!("connection error: {}", e);
            }
        });
    }
}

struct ServerState {
    tunnels: HashMap<Uuid, tokio::sync::oneshot::Sender<TcpStream>>,
}

#[instrument(skip(stream, state, secret), fields(addr = %addr))]
async fn handle_connection(
    mut stream: TcpStream,
    addr: SocketAddr,
    state: Arc<Mutex<ServerState>>,
    secret: Option<String>,
) -> anyhow::Result<()> {
    info!("incoming connection");

    // If secret is set, send challenge
    if let Some(_ref_secret) = &secret {
        let challenge = Uuid::new_v4();
        send_message(&mut stream, &ControlMessage::Challenge(challenge)).await?;

        // Now we wait for either Authenticate (control) or Accept (tunnel)
        // Wait, does Accept also require authentication?
        // Let's assume the first message will tell us.
    }

    let mut reader = tokio::io::BufReader::new(stream);
    let msg = recv_message(&mut reader).await?;

    match msg {
        ControlMessage::Authenticate(auth) => {
            // TODO: verify auth
            info!("client authenticated");
            // After auth, we expect Hello
            let msg = recv_message(&mut reader).await?;
            if let ControlMessage::Hello(port) = msg {
                handle_control(reader.into_inner(), port, state).await?;
            }
        }
        ControlMessage::Hello(port) => {
            if secret.is_some() {
                return Err(anyhow::anyhow!("authentication required"));
            }
            handle_control(reader.into_inner(), port, state).await?;
        }
        ControlMessage::Accept(id) => {
            let mut state_guard = state.lock().await;
            if let Some(tx) = state_guard.tunnels.remove(&id) {
                let _ = tx.send(reader.into_inner());
            }
        }
        _ => {
            warn!("unexpected message");
        }
    }

    Ok(())
}

async fn handle_control(
    mut stream: TcpStream,
    requested_port: u16,
    state: Arc<Mutex<ServerState>>,
) -> anyhow::Result<()> {
    // For now, just pick the requested port or a random one
    let port = if requested_port == 0 {
        // pick a random port (just a placeholder for now)
        61426 
    } else {
        requested_port
    };

    info!(host = "0.0.0.0", port = port, "new client");
    send_message(&mut stream, &ControlMessage::Hello(port)).await?;

    // Now listen on the tunnel port
    let tunnel_listener = TcpListener::bind(format!("0.0.0.0:{}", port)).await?;

    loop {
        let (mut client_stream, _addr) = tunnel_listener.accept().await?;
        let id = Uuid::new_v4();

        let (tx, rx) = tokio::sync::oneshot::channel();
        {
            let mut state_guard = state.lock().await;
            state_guard.tunnels.insert(id, tx);
        }

        send_message(&mut stream, &ControlMessage::Connection(id)).await?;

        // Wait for the tunnel connection to be established
        if let Ok(mut tunnel_stream) = rx.await {
            tokio::spawn(async move {
                let _ = tokio::io::copy_bidirectional(&mut client_stream, &mut tunnel_stream).await;
            });
        }
    }
}
EOF
"}

